#!/usr/bin/env python3
"""Original MIT tile guest, ST-058 §§4–5/8/11–13; adjacent LICENSE.

All pattern tables, character pixels, palettes and window registers are written
by SH-2 instructions. No SDK, compiler objects, emulator detection or host drawing.
"""
import argparse
import hashlib
import importlib.util
from pathlib import Path
import struct
HERE = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('assembler', HERE.parents[1] / 'homebrew/star-collector/build.py')
assembler = importlib.util.module_from_spec(spec)
spec.loader.exec_module(assembler)

def store(address, value, width='w'):
    return f'load {address:#x},r1\nload {value:#x},r0\nmov.{width} r0,@r1\n'

def build():
    source = '; Original MIT four-layer tile diagnostic. Generated by build_tiles.py.\n'
    # A supplies four names; B supplies five character reads. Keeping all
    # of these in A would exceed its eight access timings.
    for off, value in [(0,0x8000),(0x10,0x0123),(0x12,0xFFFF),
                       (0x18,0x4556),(0x1A,0xFFF7),(0x20,15),(0x28,0x1000),(0x2A,1),
                       (0x30,0x8008),(0x32,0),(0x34,0x8008),(0x36,0xC008),
                       (0x40,8),(0x44,5),(0x48,48),(0x4C,14),
                       (0x78,1),(0x7C,1),(0x88,1),(0x8C,1),
                       (0xF8,0x0607),(0xFA,0x0405),(0xAC,3),(0xAE,0xF800),
                       (0xC0,64),(0xC2,0),(0xC4,70),(0xC6,7),(0xD2,0x0200)]:
        source += store(0x25F80000+off,value)
    for at,value in [(0x10000,0x100),(0x14004,0),(0x14006,0x2110),
                     (0x18002,0x48),(0x1C008,0x140)]:
        source += store(0x25E00000+at,value)
    for i,value in enumerate([0,0x1F,0x3E0,0x7C00,0x7FFF]): source += store(0x25F00000+2*i,value)
    for n,(at,value,count) in enumerate([(0x2000,0x11111111,8),(0x2200,0x02020202,16),
                                       (0x2400,0x33333333,32),(0x2800,0x44444444,8)]):
        source += f'load {0x25E40000+at:#x},r1\nload {value:#x},r0\nmov #{count},r2\nfill{n}:\nmov.l r0,@r1\nadd #4,r1\ndt r2\nbf fill{n}\n'
    source += store(0x06009000,0x600D,'l')+'park:\nsleep\nbra park\nnop\n'
    code = assembler.assemble(source, base=0x200)
    chunks = [(0,struct.pack('>II',0x200,0x06100000)),(0x200,code)]
    rom=bytearray(524288)
    lines=['# Original MIT four-layer tile BIOS fixture. Adjacent LICENSE.', '# Generated by build_tiles.py; unspecified bytes zero.']
    for at,chunk in chunks:
        rom[at:at+len(chunk)]=chunk
        for i in range(0,len(chunk),16):
            words=struct.unpack('>'+'H'*(len(chunk[i:i+16])//2),chunk[i:i+16])
            lines.append(f'{at+i:04X} '+' '.join(f'{w:04X}' for w in words))
    return source, '\n'.join(lines)+'\n', hashlib.sha256(rom).hexdigest()

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
    source,text,digest=build()
    for path,value in [(HERE/'tiles.s',source),(HERE/'tiles.hex',text)]:
        if args.check: assert path.read_text()==value,f'Rebuild {path.name}'
        else: path.write_text(value)
    print(f'{"Verified" if args.check else "Built"} tiles.hex; expanded ROM SHA-256 {digest}')
